268	// persistDefinition is the canonical, already-validated constraint set bound
269	// to one circuit version. The public/private partition is owned by the
270	// circuit record and is deliberately not duplicated here, so it can never
271	// drift from the declared counts.
272	type persistDefinition struct {
273		Modulus     string              `json:"modulus"`
274		Constraints []persistConstraint `json:"constraints"`
275	}
276	
277	// persistArtifact is a compiled artifact: the version's identity and
278	// constraint count bound to its recomputable SHA-256 hash.
279	type persistArtifact struct {
280		Name        string `json:"name"`
281		Version     int    `json:"version"`
282		Modulus     int64  `json:"modulus"`
283		Constraints int    `json:"constraints"`
284		Hash        string `json:"hash"`
285	}
