287	type persistCircuit struct {
288		Name          string             `json:"name"`
289		Version       int                `json:"version"`
290		Constraints   int                `json:"constraints"`
291		PublicInputs  int                `json:"public_inputs"`
292		PrivateInputs int                `json:"private_inputs"`
293		Frozen        bool               `json:"frozen"`
294		Description   string             `json:"description"`
295		Definition    *persistDefinition `json:"definition,omitempty"`
296	}
297	
298	// Strict decoding of committed circuit records.
299	//
300	// A circuit record in data.json must name each of name, version, constraints,
301	// public_inputs, private_inputs, frozen and description exactly once, with
302	// the exact JSON type the writer emits (string / integer / integer / integer
303	// / integer / boolean / string). A missing key, a null, a wrong type or a
304	// repeated key is data corruption and refuses the whole directory read: a
305	// missing or null frozen flag must not silently read as false (turning a
306	// frozen version back into an editable draft), and a repeated key must not
307	// resolve to its last value. An explicit 0, false or "" is an ordinary value
308	// and stays legal. The definition member remains the one optional field: it
309	// may be absent or null (the legacy counts-only state); when present it goes
310	// through the strict persistDefinition decoder.
311	//
312	// Only shape is judged here. The domain rules (non-blank name, positive
313	// version and constraint count, non-negative input counts) keep being
314	// re-checked by validateEnvelope.
315	
316	var persistCircuitFields = []string{
317		"name", "version", "constraints", "public_inputs", "private_inputs",
318		"frozen", "description", "definition",
319	}
320	
321	// storedRecordShape is the shared strict-JSON rule set (definition_schema.go)
322	// tagged for committed data: every structural failure in a stored circuit
323	// record is data corruption, never a bad request.
324	var storedRecordShape = jsonShape{fail: corruptf}
325	
326	func (c *persistCircuit) UnmarshalJSON(raw []byte) error {
327		const what = "stored circuit record"
328		if string(bytes.TrimSpace(raw)) == "null" {
329			return corruptf("%s must be a JSON object, not null", what)
330		}
331		members, err := strictCircuitObject(raw, what)
332		if err != nil {
333			return err
334		}
335	
336		var out persistCircuit
337	
338		requireString := func(key string, dst *string) error {
339			r, err := storedRecordShape.require(members, key, what)
340			if err != nil {
341				return err
342			}
343			v, err := storedRecordShape.string(r, what+" field "+strconv.Quote(key))
344			if err != nil {
345				return err
346			}
347			*dst = v
348			return nil
349		}
350		requireInt := func(key string, dst *int) error {
351			r, err := storedRecordShape.require(members, key, what)
352			if err != nil {
353				return err
354			}
355			v, err := storedRecordShape.int(r, what+" field "+strconv.Quote(key))
356			if err != nil {
357				return err
358			}
359			*dst = v
360			return nil
361		}
362	
363		if err := requireString("name", &out.Name); err != nil {
364			return err
365		}
366		if err := requireInt("version", &out.Version); err != nil {
367			return err
368		}
369		if err := requireInt("constraints", &out.Constraints); err != nil {
370			return err
371		}
372		if err := requireInt("public_inputs", &out.PublicInputs); err != nil {
373			return err
374		}
375		if err := requireInt("private_inputs", &out.PrivateInputs); err != nil {
376			return err
377		}
378		frozenRaw, err := storedRecordShape.require(members, "frozen", what)
379		if err != nil {
380			return err
381		}
382		out.Frozen, err = storedRecordShape.bool(frozenRaw, what+" field "+strconv.Quote("frozen"))
383		if err != nil {
384			return err
385		}
386		if err := requireString("description", &out.Description); err != nil {
387			return err
388		}
389	
390		// definition is the only optional member: absent or null both mean the
391		// counts-only legacy state.
392		if defRaw, present := members["definition"]; present {
393			if string(bytes.TrimSpace(defRaw)) != "null" {
394				var def persistDefinition
395				if err := json.Unmarshal(defRaw, &def); err != nil {
396					var se StoreError
397					if errors.As(err, &se) {
398						return err // already reported as data corruption
399					}
400					return corruptf("%s field %s is not a valid constraint definition: %v", what, strconv.Quote("definition"), err)
401				}
402				out.Definition = &def
403			}
404		}
405	
406		*c = out
407		return nil
408	}
409	
410	// strictCircuitObject decodes one committed circuit record's own member map,
411	// demanding a JSON object with exactly the known top-level fields once.
412	func strictCircuitObject(raw []byte, what string) (map[string]json.RawMessage, error) {
413		return strictObjectMembers(raw, what, persistCircuitFields)
414	}
415	
416	// strictObjectMembers decodes one committed record's own member map,
417	// demanding a JSON object without repeated keys. A non-nil allowed list
418	// restricts which keys may appear; nil allows any key. It scans only the
419	// record's own level: the envelope scanner already attributes a duplicated
420	// top-level key to this record, and nested values such as the constraint
421	// definition own their (more precise) strict decoders. Keys are compared
422	// after JSON unescaping, so a field repeated through a \uXXXX spelling is
423	// still a duplicate, even when both values are identical.
424	func strictObjectMembers(raw []byte, what string, allowedFields []string) (map[string]json.RawMessage, error) {
425		trimmed := bytes.TrimSpace(raw)
426		if len(trimmed) == 0 || trimmed[0] != '{' {
427			return nil, corruptf("%s must be a JSON object", what)
428		}
429		dec := json.NewDecoder(bytes.NewReader(trimmed))
430		dec.UseNumber()
431		open, err := dec.Token()
432		if err != nil || open != json.Delim('{') {
433			return nil, corruptf("%s must be a JSON object", what)
434		}
435		var allowed map[string]bool
436		if allowedFields != nil {
437			allowed = make(map[string]bool, len(allowedFields))
438			for _, f := range allowedFields {
439				allowed[f] = true
440			}
441		}
442		members := make(map[string]json.RawMessage)
443		for dec.More() {
444			keyTok, err := dec.Token()
445			if err != nil {
446				return nil, corruptf("%s is not valid JSON: %v", what, err)
447			}
448			key, ok := keyTok.(string)
449			if !ok {
450				return nil, corruptf("%s is not valid JSON", what)
451			}
452			if allowed != nil && !allowed[key] {
453				return nil, corruptf("%s has unknown field %q", what, key)
454			}
455			if _, repeated := members[key]; repeated {
456				return nil, corruptf("%s contains duplicate field %q", what, key)
457			}
458			var value json.RawMessage
459			if err := dec.Decode(&value); err != nil {
460				return nil, corruptf("%s is not valid JSON: %v", what, err)
461			}
462			members[key] = value
463		}
464		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
465			return nil, corruptf("%s is not valid JSON", what)
466		}
467		if _, err := dec.Token(); err != io.EOF {
468			return nil, corruptf("%s is not valid JSON: trailing data after the object", what)
469		}
470		return members, nil
471	}
472	
473	type persistSetup struct {
474		Name    string `json:"name"`
475		Version int    `json:"version"`
476	}
477	
478	type persistJob struct {
479		ID       string `json:"id"`
480		Circuit  string `json:"circuit"`
481		Version  int    `json:"version"`
482		Kind     string `json:"kind"`
483		Attempt  int    `json:"attempt"`
484		Artifact string `json:"artifact,omitempty"`
485		// CompiledHash is the optional binding to the pinned version's compiled
486		// artifact, stored exactly as submitted.
487		CompiledHash string `json:"compiled_hash,omitempty"`
488	}
489	
490	// compiledHashKey is the canonical spelling of a job record's
491	// compiled-artifact binding field.
492	const compiledHashKey = "compiled_hash"
493	
494	// isCompiledHashKey reports whether key names the compiled-artifact binding
495	// field, allowing differences in ASCII letter case only: "compiled_hash",
496	// "COMPILED_HASH" and every mixed-case spelling are the same field. Keys are
497	// already JSON-unescaped at this point, so an escaped spelling of any of
498	// these forms lands here too. Non-ASCII lookalikes never match.
499	func isCompiledHashKey(key string) bool {
500		if len(key) != len(compiledHashKey) {
501			return false
502		}
503		for i := 0; i < len(key); i++ {
504			c := key[i]
505			if c >= 'A' && c <= 'Z' {
506				c += 'a' - 'A'
507			}
508			if c != compiledHashKey[i] {
509				return false
510			}
511		}
512		return true
513	}
514	
515	// Strict decoding of the compiled-artifact binding on a committed job record.
516	//
517	// compiled_hash is a field whose presence is meaningful: records written
518	// before bindings existed simply omit it, and an explicit "" is the unbound
519	// state. But once the key appears its value must be a JSON string. A null is
520	// not "no binding" — it is damage to a binding the record claims to carry,
521	// and so is a number, boolean, array or object in its place. Reading either
522	// as the zero string would silently turn a bound job into an unbound one
523	// (and the next commit would drop the field entirely), so the read is
524	// refused as data corruption instead. A repeated key — including one
525	// repeated through JSON string escapes, even with identical values — is
526	// likewise refused rather than resolved to its last value. A legal non-empty
527	// string keeps being matched against the pinned version's artifact by
528	// validateEnvelope, exactly as written.
529	//
530	// The field is recognized under any ASCII letter-case spelling, so a record
531	// carrying "COMPILED_HASH" (or any mixed-case form, escaped or not) is the
532	// same binding and follows the same rules: a single such key is read with
533	// the full string validation above, and two spellings of the field on one
534	// record — even with byte-identical values — are a duplicate binding and
535	// corrupt the read rather than being resolved by key order.
536	//
537	// Only the binding field is judged here; every other field keeps the
538	// ordinary struct decoding.
539	func (j *persistJob) UnmarshalJSON(raw []byte) error {
540		const what = "stored job record"
541		if string(bytes.TrimSpace(raw)) == "null" {
542			return corruptf("%s must be a JSON object, not null", what)
543		}
544		members, err := strictObjectMembers(raw, what, nil)
545		if err != nil {
546			return err
547		}
548		// Name the job in a binding-field failure when its id is legible; the id
549		// itself is decoded for real by the ordinary pass below.
550		where := what
551		if idRaw, ok := members["id"]; ok {
552			if id, idErr := storedRecordShape.string(idRaw, what+` field "id"`); idErr == nil {
553				where = fmt.Sprintf("stored job record %q", id)
554			}
555		}
556		// Every spelling of the binding field counts as the same one field; the
557		// record may carry it at most once, however it is capitalized.
558		var bindingKeys []string
559		for key := range members {
560			if isCompiledHashKey(key) {
561				bindingKeys = append(bindingKeys, key)
562			}
563		}
564		if len(bindingKeys) > 1 {
565			sort.Strings(bindingKeys)
566			quoted := make([]string, len(bindingKeys))
567			for i, k := range bindingKeys {
568				quoted[i] = strconv.Quote(k)
569			}
570			return corruptf("%s carries the binding field %q more than once (as %s)",
571				where, compiledHashKey, strings.Join(quoted, ", "))
572		}
573		compiledHash := ""
574		hasBinding := false
575		if len(bindingKeys) == 1 {
576			hash, err := storedRecordShape.string(members[bindingKeys[0]], where+` field "compiled_hash"`)
577			if err != nil {
578				return err
579			}
580			compiledHash, hasBinding = hash, true
581		}
582		type plainJob persistJob
583		var decoded plainJob
584		if err := json.Unmarshal(raw, &decoded); err != nil {
585			return corruptf("%s is not valid JSON: %v", what, err)
586		}
587		if hasBinding {
588			decoded.CompiledHash = compiledHash
589		}
590		*j = persistJob(decoded)
591		return nil
592	}
593	
594	// Store is a persistent workbench backed by one local data directory.
595	//
596	// All operations are safe for concurrent use by multiple goroutines and by
597	// several processes pointed at the same directory: an in-process mutex plus a
598	// process-shared flock serialize commits, and every commit is an atomic
599	// temp-file/fsync/rename replacement. Open the directory with Open and call
600	// Close when done.
601	type Store struct {
602		dir  string
603		mu   sync.Mutex
604		lock *os.File
605	
606		data envelope
607	}
608	
609	// Open opens (creating if needed) the workbench data in dir. If the
610	// directory does not exist it is created. Existing committed data is loaded
611	// and fully validated before Open returns; on a corrupt, truncated or
612	// unsupported-format file Open returns an error wrapping ErrDataCorrupt and
613	// leaves every file in the directory untouched.
614	func Open(dir string) (*Store, error) {
615		if dir == "" {
616			return nil, invalidf("data directory must not be empty")
617		}
618		if err := os.MkdirAll(dir, 0o755); err != nil {
619			return nil, fmt.Errorf("cannot create data directory %q: %w", dir, err)
620		}
621		lockPath := filepath.Join(dir, dirLockFile)
622		lock, err := os.OpenFile(lockPath, os.O_RDWR|os.O_CREATE, 0o644)
623		if err != nil {
624			return nil, fmt.Errorf("cannot open lock file in %q: %w", dir, err)
625		}
626		// Serialize against other processes while we read / validate.
627		if err := lockExclusive(lock); err != nil {
628			lock.Close()
629			return nil, fmt.Errorf("cannot lock data directory %q: %w", dir, err)
630		}
631	
632		s := &Store{dir: dir, lock: lock}
633		if err := s.loadLocked(); err != nil {
634			unlockLock(lock)
635			lock.Close()
636			return nil, err
637		}
638		// The lock is taken again per operation; holding it for the store's
639		// lifetime would forbid two open handles on one directory.
640		if err := unlockLock(lock); err != nil {
641			lock.Close()
642			return nil, fmt.Errorf("cannot release open lock on %q: %w", dir, err)
643		}
644		return s, nil
645	}
646	
647	// Close releases the directory lock. It does not discard committed data.
648	func (s *Store) Close() error {
649		s.mu.Lock()
650		defer s.mu.Unlock()
651		if s.lock == nil {
652			return nil
653		}
654		var first error
655		if err := unlockLock(s.lock); err != nil {
656			first = err
657		}
658		if err := s.lock.Close(); err != nil && first == nil {
659			first = err
660		}
661		s.lock = nil
662		return first
663	}
664	
665	// Dir reports the data directory backing the store.
666	func (s *Store) Dir() string { return s.dir }
667	
668	func (s *Store) dataPath() string { return filepath.Join(s.dir, dirDataFile) }
669	func (s *Store) tmpPath() string  { return filepath.Join(s.dir, dirTmpFile) }
670	
671	// loadLocked reads and validates the committed file. Caller must hold the
672	// exclusive flock; the in-process mutex is taken by the public Open path.
673	func (s *Store) loadLocked() error {
674		raw, err := os.ReadFile(s.dataPath())
675		if errors.Is(err, os.ErrNotExist) {
676			s.data = envelope{Format: FormatVersion}
677			return nil
678		}
679		if err != nil {
680			return fmt.Errorf("cannot read data file %q: %w", s.dataPath(), err)
681		}
682		if len(strings.TrimSpace(string(raw))) == 0 {
683			return corruptf("data file %q is empty or truncated; refusing to treat it as a new directory", s.dataPath())
684		}
685	
686		var env envelope
687		if err := json.Unmarshal(raw, &env); err != nil {
688			// Shape failures surfaced by the persisted-definition decoders are
689			// integrity failures, not JSON syntax errors; report their detail
690			// instead of the generic "not valid JSON" wording.
691			var se StoreError
692			if errors.As(err, &se) && se.Kind == ErrDataCorrupt.Kind {
693				return corruptf("data file %q failed integrity validation: %s; original file left in place", s.dataPath(), se.Detail)
694			}
695			return corruptf("data file %q is not valid JSON (%v); original file left in place", s.dataPath(), err)
696		}
697		if env.Format == 0 {
698			return corruptf("data file %q has no format version; original file left in place", s.dataPath())
699		}
700		if env.Format != FormatVersion {
701			return corruptf("data file %q uses unsupported format version %d (this build supports %d); original file left in place",
702				s.dataPath(), env.Format, FormatVersion)
703		}
704		if err := validateEnvelope(env); err != nil {
705			return corruptf("data file %q failed integrity validation: %v; original file left in place", s.dataPath(), err)
706		}
707		s.data = env
708		return nil
709	}
710	
711	// commitLocked writes the pending state atomically: temp file → fsync →
712	// rename → fsync directory. Caller must hold both the in-process mutex and
713	// the exclusive flock; all in-memory mutations must already have happened and
714	// been rule-checked, so a failure here occurs before any success is reported.
715	func (s *Store) commitLocked() error {
716		s.data.Format = FormatVersion
717		// Stable output: records are stored sorted so files are deterministic.
718		sortEnvelope(&s.data)
719	
720		payload, err := json.MarshalIndent(&s.data, "", "  ")
721		if err != nil {
722			return fmt.Errorf("cannot encode data: %w", err)
723		}
724		payload = append(payload, '\n')
725	
726		tmp := s.tmpPath()
727		f, err := os.OpenFile(tmp, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o644)
728		if err != nil {
729			return fmt.Errorf("cannot stage write in %q: %w", s.dir, err)
730		}
731		if _, err := f.Write(payload); err != nil {
732			f.Close()
733			os.Remove(tmp)
734			return fmt.Errorf("cannot write staged data: %w", err)
735		}
736		if err := f.Sync(); err != nil {
737			f.Close()
738			os.Remove(tmp)
739			return fmt.Errorf("cannot flush staged data: %w", err)
740		}
741		if err := f.Close(); err != nil {
742			os.Remove(tmp)
743			return fmt.Errorf("cannot finish staged data: %w", err)
744		}
745		if err := os.Rename(tmp, s.dataPath()); err != nil {
746			os.Remove(tmp)
747			return fmt.Errorf("cannot commit data file: %w", err)
748		}
749		if err := syncDir(s.dir); err != nil {
750			// The rename already happened; lack of dir fsync only weakens crash
751			// durability, never correctness of what is visible now.
752			return nil
753		}
754		return nil
755	}
756	
757	// withLock runs fn under the in-process mutex and an exclusive flock, then
758	// atomically commits when fn requests it. The on-disk state is re-read after
759	// acquiring the lock, so concurrent commits from another process or another
760	// handle are always observed. Operations validate before mutating; a rejected
761	// operation (commit=false or an error) writes nothing and leaves committed
762	// state unchanged.
763	func (s *Store) withLock(fn func() (commit bool, err error)) error {
764		s.mu.Lock()
765		defer s.mu.Unlock()
766		if s.lock == nil {
767			return invalidf("store is closed")
768		}
769		if err := lockExclusive(s.lock); err != nil {
770			return fmt.Errorf("cannot lock data directory: %w", err)
771		}
772		defer unlockLock(s.lock)
773	
774		if err := s.loadLocked(); err != nil {
775			return err
776		}
777		commit, err := fn()
778		if err != nil {
779			return err
780		}
781		if !commit {
782			return nil
783		}
784		return s.commitLocked()
785	}
786	
787	// withLockRead runs fn under a shared flock over freshly reloaded state.
788	func (s *Store) withLockRead(fn func() error) error {
789		s.mu.Lock()
790		defer s.mu.Unlock()
791		if s.lock == nil {
792			return invalidf("store is closed")
793		}
794		if err := lockShared(s.lock); err != nil {
795			return fmt.Errorf("cannot lock data directory: %w", err)
796		}
797		defer unlockLock(s.lock)
798		if err := s.loadLocked(); err != nil {
799			return err
800		}
801		return fn()
802	}
803	
804	func sortEnvelope(env *envelope) {
805		sort.Slice(env.Circuits, func(i, j int) bool {
806			if env.Circuits[i].Name != env.Circuits[j].Name {
807				return env.Circuits[i].Name < env.Circuits[j].Name
808			}
809			return env.Circuits[i].Version < env.Circuits[j].Version
810		})
811		sort.Slice(env.Setups, func(i, j int) bool {
812			if env.Setups[i].Name != env.Setups[j].Name {
813				return env.Setups[i].Name < env.Setups[j].Name
814			}
815			return env.Setups[i].Version < env.Setups[j].Version
816		})
817		sort.Slice(env.Jobs, func(i, j int) bool { return env.Jobs[i].ID < env.Jobs[j].ID })
818		sort.Slice(env.Artifacts, func(i, j int) bool {
819			if env.Artifacts[i].Name != env.Artifacts[j].Name {
820				return env.Artifacts[i].Name < env.Artifacts[j].Name
821			}
822			return env.Artifacts[i].Version < env.Artifacts[j].Version
823		})
824	}
825	
826	// validateEnvelope re-checks every invariant on load so a tampered or
827	// hand-edited file cannot bypass the domain rules.
828	func validateEnvelope(env envelope) error {
829		seenCircuit := make(map[[2]string]bool)
830		circuitOK := make(map[[2]string]bool)
831		for i, c := range env.Circuits {
832			key := [2]string{c.Name, itoa(c.Version)}
833			if c.Name == "" || strings.TrimSpace(c.Name) == "" {
834				return fmt.Errorf("circuit #%d has an empty or blank name", i+1)
835			}
836			if c.Version <= 0 {
837				return fmt.Errorf("circuit %q version %d is not a positive integer", c.Name, c.Version)
838			}
839			if seenCircuit[key] {
840				return fmt.Errorf("circuit %q version %d appears more than once", c.Name, c.Version)
841			}
842			seenCircuit[key] = true
843			if c.Constraints <= 0 {
844				return fmt.Errorf("circuit %q v%d: constraints must be > 0", c.Name, c.Version)
845			}
846			if c.PublicInputs < 0 || c.PrivateInputs < 0 {
847				return fmt.Errorf("circuit %q v%d: input counts must not be negative", c.Name, c.Version)
848			}
849			// The same representability rule the write path enforces: wire 0 plus
850			// every declared input must fit inside the platform's int. A record
851			// beyond that bound can never have been written by this build and
852			// cannot be checked safely, so the directory is corrupt rather than
853			// silently narrowed or read with a wrapped-around layout.
854			if !inputLayoutRepresentable(c.PublicInputs, c.PrivateInputs) {
855				return fmt.Errorf("circuit %q v%d: input layout is not representable: 1 constant wire + %d public + %d private inputs exceeds the platform limit of %d wires",
856					c.Name, c.Version, c.PublicInputs, c.PrivateInputs, maxInputWires)
857			}
858			if c.Definition != nil {
859				if err := validatePersistDefinition(c.Name, c.Version, c.Constraints, c.PublicInputs, c.PrivateInputs, c.Definition); err != nil {
860					return err
861				}
862			}
863			circuitOK[key] = true
864		}
865		seenSetup := make(map[[2]string]bool)
866		for i, p := range env.Setups {
867			key := [2]string{p.Name, itoa(p.Version)}
868			if !circuitOK[key] {
869				return fmt.Errorf("setup #%d belongs to unknown circuit %q v%d", i+1, p.Name, p.Version)
870			}
871			c := findPersistCircuit(env.Circuits, p.Name, p.Version)
872			if c == nil || !c.Frozen {
873				return fmt.Errorf("setup belongs to non-frozen circuit %q v%d", p.Name, p.Version)
874			}
875			if seenSetup[key] {
876				return fmt.Errorf("setup for %q v%d appears more than once", p.Name, p.Version)
877			}
878			seenSetup[key] = true
879		}
880		seenJob := make(map[string]bool)
881		for i, j := range env.Jobs {
882			if j.ID == "" || strings.TrimSpace(j.ID) == "" {
883				return fmt.Errorf("job #%d has an empty or blank id", i+1)
884			}
885			if seenJob[j.ID] {
886				return fmt.Errorf("job %q appears more than once", j.ID)
887			}
888			seenJob[j.ID] = true
889			if j.Kind != "prove" {
890				return fmt.Errorf("job %q has unsupported kind %q", j.ID, j.Kind)
891			}
892			if j.Attempt <= 0 {
893				return fmt.Errorf("job %q: attempt must be a positive integer", j.ID)
894			}
895			key := [2]string{j.Circuit, itoa(j.Version)}
896			if !circuitOK[key] {
897				return fmt.Errorf("job %q binds to unknown circuit %q v%d", j.ID, j.Circuit, j.Version)
898			}
899			c := findPersistCircuit(env.Circuits, j.Circuit, j.Version)
900			if c == nil || !c.Frozen {
901				return fmt.Errorf("job %q binds to non-frozen circuit %q v%d", j.ID, j.Circuit, j.Version)
902			}
903			if !seenSetup[key] {
904				return fmt.Errorf("job %q binds to circuit %q v%d without a trusted setup", j.ID, j.Circuit, j.Version)
905			}
906			// A recorded compiled-artifact binding must still resolve against the
907			// pinned version's artifact; a dangling or mismatched binding makes
908			// the file unreadable rather than silently dropping the binding.
909			if j.CompiledHash != "" {
910				artifact := findArtifact(env.Artifacts, j.Circuit, j.Version)
911				if artifact == nil {
912					return fmt.Errorf("job %q binds to compiled artifact of %q v%d which is missing", j.ID, j.Circuit, j.Version)
913				}
914				if artifact.Hash != j.CompiledHash {
915					return fmt.Errorf("job %q compiled hash %q does not match the artifact of %q v%d (hash %q)",
916						j.ID, j.CompiledHash, j.Circuit, j.Version, artifact.Hash)
917				}
918			}
919		}
920		seenArtifact := make(map[[2]string]bool)
921		for i, a := range env.Artifacts {
922			key := [2]string{a.Name, itoa(a.Version)}
923			if !circuitOK[key] {
924				return fmt.Errorf("artifact #%d belongs to unknown circuit %q v%d", i+1, a.Name, a.Version)
925			}
926			c := findPersistCircuit(env.Circuits, a.Name, a.Version)
927			if c == nil || !c.Frozen {
928				return fmt.Errorf("artifact belongs to non-frozen circuit %q v%d", a.Name, a.Version)
929			}
930			if seenArtifact[key] {
931				return fmt.Errorf("artifact for %q v%d appears more than once", a.Name, a.Version)
932			}
933			seenArtifact[key] = true
934			if c.Definition == nil {
935				return fmt.Errorf("artifact for %q v%d has no constraint definition", a.Name, a.Version)
936			}
937			if a.Constraints != c.Constraints {
938				return fmt.Errorf("artifact for %q v%d constraint count %d disagrees with the version's %d",
939					a.Name, a.Version, a.Constraints, c.Constraints)
940			}
941			def, err := definitionFromPersist(*c.Definition, c.PublicInputs, c.PrivateInputs)
942			if err != nil {
943				return fmt.Errorf("artifact for %q v%d cannot be checked against its definition: %w", a.Name, a.Version, err)
944			}
945			if int64(a.Modulus) != def.modulus || len(def.constraints) != a.Constraints {
946				return fmt.Errorf("artifact for %q v%d is inconsistent with its stored definition", a.Name, a.Version)
947			}
948			wantHash := artifactHash(a.Name, a.Version, def)
949			if a.Hash != wantHash {
950				return fmt.Errorf("artifact for %q v%d hash %q does not recompute from the definition (want %q)",
951					a.Name, a.Version, a.Hash, wantHash)
952			}
953		}
954		return nil
955	}
956	
957	// validatePersistDefinition re-validates a stored definition against its
958	// version's declared counts: prime modulus, in-range wires and an exact
959	// constraint count match.
960	func validatePersistDefinition(name string, version, constraints, public, private int, def *persistDefinition) error {
961		parsed, err := definitionFromPersist(*def, public, private)
962		if err != nil {
963			return fmt.Errorf("circuit %q v%d has a corrupt constraint definition: %w", name, version, err)
964		}
965		if !parsed.compatibleWith(constraints, public, private) {
966			return fmt.Errorf("circuit %q v%d definition is incompatible with its declared counts", name, version)
967		}
968		return nil
969	}
970	
971	func findPersistCircuit(cs []persistCircuit, name string, version int) *persistCircuit {
972		for i := range cs {
973			if cs[i].Name == name && cs[i].Version == version {
974				return &cs[i]
975			}
976		}
977		return nil
978	}
979	
980	func itoa(v int) string { return fmt.Sprintf("%d", v) }
981

