1	package zkcircuit
2	
3	import (
4		"errors"
5		"strings"
6		"testing"
7	)
8	
9	// Regression tests for the compiled-artifact binding as expressed in a
10	// committed job record. compiled_hash may be omitted (legacy register-only
11	// records) or be an explicit string ("" = unbound, anything else = the exact
12	// artifact hash). Any other value — null above all — is damage to a binding
13	// the record claims to carry, never "the user did not provide a hash": the
14	// directory read is refused as data corruption, the error names the job, and
15	// the file is left byte-for-byte in place.
16	
17	// seedBoundJobStore commits a frozen, compiled circuit with a trusted setup
18	// and two jobs — "j-bound" carrying the version's artifact hash and "j-plain"
19	// left unbound — and returns the data directory and the artifact hash.
20	func seedBoundJobStore(t *testing.T) (dir, hash string) {
21		t.Helper()
22		dir = t.TempDir()
23		s, err := Open(dir)
24		if err != nil {
25			t.Fatal(err)
26		}
27		hash = compiledVersion(t, s, "c", 1, validDef)
28		if _, err := s.SubmitJob(boundProveJob("j-bound", "c", 1, hash)); err != nil {
29			t.Fatal(err)
30		}
31		if _, err := s.SubmitJob(boundProveJob("j-plain", "c", 1, "")); err != nil {
32			t.Fatal(err)
33		}
34		if err := s.Close(); err != nil {
35			t.Fatal(err)
36		}
37		return dir, hash
38	}
39	
40	// rewriteBoundHash replaces the committed j-bound binding field with the
41	// given raw JSON text, returning the damaged file content.
42	func rewriteBoundHash(t *testing.T, dir, hash, replacement string) string {
43		t.Helper()
44		valid, err := readDataFile(t, dir)
45		if err != nil {
46			t.Fatal(err)
47		}
48		field := `"compiled_hash": "` + hash + `"`
49		if !strings.Contains(string(valid), field) {
50			t.Fatalf("committed file does not carry the bound field %q", field)
51		}
52		bad := strings.Replace(string(valid), field, `"compiled_hash": `+replacement, 1)
53		writeDataFile(t, dir, []byte(bad))
54		return bad
55	}
56	
57	// A compiled_hash that is present but not a JSON string is data corruption:
58	// null, numbers, booleans, arrays and objects are all refused, the error
59	// names the job whose binding field is damaged, and the file is untouched.
60	func TestJobCompiledHashNonStringIsCorrupt(t *testing.T) {
61		cases := []struct {
62			name  string
63			value string
64		}{
65			{"null", "null"},
66			{"number", "5"},
67			{"boolean", "true"},
68			{"array", `["deadbeef"]`},
69			{"object", `{"hash":"deadbeef"}`},
70		}
71		for _, tc := range cases {
72			t.Run(tc.name, func(t *testing.T) {
73				dir, h := seedBoundJobStore(t)
74				bad := rewriteBoundHash(t, dir, h, tc.value)
75	
76				_, err := Open(dir)
77				if !errors.Is(err, ErrDataCorrupt) {
78					t.Fatalf("want ErrDataCorrupt, got %v", err)
79				}
80				if !strings.Contains(err.Error(), `"j-bound"`) {
81					t.Fatalf("error does not name the damaged job: %v", err)
82				}
83				if !strings.Contains(err.Error(), "compiled_hash") {
84					t.Fatalf("error does not name the binding field: %v", err)
85				}
86				got, rerr := readDataFile(t, dir)
87				if rerr != nil {
88					t.Fatal(rerr)
89				}
90				if string(got) != bad {
91					t.Fatalf("open modified the damaged file")
92				}
93				// A second open still refuses; nothing recovers the field by
94				// guessing from the current artifact.
95				if _, err := Open(dir); !errors.Is(err, ErrDataCorrupt) {
96					t.Fatalf("reopen on damaged dir: want corruption, got %v", err)
97				}
98			})
99		}
100	}
101	
102	// A repeated compiled_hash key is refused — compared after JSON unescaping
103	// and regardless of whether both values agree — instead of silently
104	// resolving the binding to the last value.
105	func TestJobCompiledHashDuplicateIsCorrupt(t *testing.T) {
106		_, h := seedBoundJobStore(t)
107		cases := []struct {
108			name        string
109			replacement string
110		}{
111			{"identical values", `"compiled_hash": "` + h + `", "compiled_hash": "` + h + `"`},
112			{"differing values", `"compiled_hash": "` + h + `", "compiled_hash": "deadbeef"`},
113			{"null then value", `"compiled_hash": null, "compiled_hash": "` + h + `"`},
114			{"escaped key spelling", `"compiled_hash": "` + h + `", "compiled\u005fhash": "` + h + `"`},
115		}
116		for _, tc := range cases {
117			t.Run(tc.name, func(t *testing.T) {
118				dir, h := seedBoundJobStore(t)
119				field := `"compiled_hash": "` + h + `"`
120				valid, err := readDataFile(t, dir)
121				if err != nil {
122					t.Fatal(err)
123				}
124				bad := strings.Replace(string(valid), field, tc.replacement, 1)
125				writeDataFile(t, dir, []byte(bad))
126	
127				_, err = Open(dir)
128				if !errors.Is(err, ErrDataCorrupt) {
129					t.Fatalf("want ErrDataCorrupt, got %v", err)
130				}
131				if !strings.Contains(err.Error(), "compiled_hash") {
132					t.Fatalf("error does not name the duplicated field: %v", err)
133				}
134				got, rerr := readDataFile(t, dir)
135				if rerr != nil {
136					t.Fatal(rerr)
137				}
138				if string(got) != bad {
139					t.Fatalf("open modified the damaged file")
140				}
141			})
142		}
143	}
144	
145	// An explicit empty string remains the legal unbound state: the directory
146	// opens and the job reads back unbound.
147	func TestJobCompiledHashExplicitEmptyStaysUnbound(t *testing.T) {
148		dir, h := seedBoundJobStore(t)
149		rewriteBoundHash(t, dir, h, `""`)
150	
151		s, err := Open(dir)
152		if err != nil {
153			t.Fatalf("explicit empty binding must load: %v", err)
154		}
155		defer s.Close()
156		got, err := s.GetJob("j-bound")
157		if err != nil {
158			t.Fatal(err)
159		}
160		if got.CompiledHash != "" {
161			t.Fatalf("explicit empty hash read as bound: %+v", got)
162		}
163	}
164	
165	// Once a directory is open, damaging the binding on disk is caught by the
166	// very next operation: reads return no partial job list, new jobs are not
167	// committed and unrelated circuit changes cannot rewrite the directory.
168	func TestOpenStoreRefusesAfterJobBindingCorruption(t *testing.T) {
169		dir, h := seedBoundJobStore(t)
170		s, err := Open(dir)
171		if err != nil {
172			t.Fatal(err)
173		}
174		defer s.Close()
175	
176		bad := rewriteBoundHash(t, dir, h, "null")
177	
178		if _, err := s.GetJob("j-bound"); !errors.Is(err, ErrDataCorrupt) {
179			t.Fatalf("GetJob after corruption: want ErrDataCorrupt, got %v", err)
180		}
181		if _, err := s.ListJobs(); !errors.Is(err, ErrDataCorrupt) {
182			t.Fatalf("ListJobs after corruption: want ErrDataCorrupt, got %v", err)
183		}
184		if _, err := s.SubmitJob(boundProveJob("j-new", "c", 1, h)); !errors.Is(err, ErrDataCorrupt) {
185			t.Fatalf("SubmitJob after corruption: want ErrDataCorrupt, got %v", err)
186		}
187		if _, err := s.CreateCircuit(Circuit{Name: "other", Version: 1, Constraints: 1}); !errors.Is(err, ErrDataCorrupt) {
188			t.Fatalf("unrelated CreateCircuit after corruption: want ErrDataCorrupt, got %v", err)
189		}
190		got, rerr := readDataFile(t, dir)
191		if rerr != nil {
192			t.Fatal(rerr)
193		}
194		if string(got) != bad {
195			t.Fatalf("damaged file was rewritten by a refused operation")
196		}
197	}
198	
199	// Legal records keep their exact shape across further commits: the bound job
200	// keeps its hash verbatim and the unbound job's omitted field is not
201	// backfilled.
202	func TestJobBindingFieldShapeSurvivesCommits(t *testing.T) {
203		dir, h := seedBoundJobStore(t)
204		s, err := Open(dir)
205		if err != nil {
206			t.Fatal(err)
207		}
208		if _, err := s.SubmitJob(boundProveJob("j-third", "c", 1, "")); err != nil {
209			t.Fatal(err)
210		}
211		if err := s.Close(); err != nil {
212			t.Fatal(err)
213		}
214		raw, err := readDataFile(t, dir)
215		if err != nil {
216			t.Fatal(err)
217		}
218		// Exactly one compiled_hash field exists: j-bound's. The two unbound jobs
219		// stay omitted rather than being rewritten with an explicit value.
220		if n := strings.Count(string(raw), `"compiled_hash"`); n != 1 {
221			t.Fatalf("committed file carries %d compiled_hash fields, want 1:\n%s", n, raw)
222		}
