		t.Fatalf("CreateCircuit after corruption: want ErrDataCorrupt, got %v", err)
	}
	if _, err := s.FreezeCircuit("c", 1); !errors.Is(err, ErrDataCorrupt) {
		t.Fatalf("FreezeCircuit after corruption: want ErrDataCorrupt, got %v", err)
	}
